121	    /// let oom = OutOfMemory::new(8192);
122	    /// assert_eq!(oom.requested_allocation_size(), 8192);
123	    /// ```
124	    #[inline]
125	    pub fn requested_allocation_size(&self) -> usize {
126	        OomOrDynError::oom_size(self.inner)
127	    }
128	}
